  jsonb_build_array(
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Появился раздел «Игры»: первая игра — «Приём пациента», клинические случаи по терапии, эндокринологии и педиатрии с баллами и разбором.'),
    jsonb_build_object('kind','new','scope','site','min_rank',4,'text','Новая роль «Учитель игры»: видит только раздел «Игры», создаёт занятие по «Приёму пациента» и выбирает случаи; ординаторы входят по коду или QR-коду со своих телефонов, а на экране учителя в реальном времени видны баллы и места.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',4,'text','«Своя игра» теперь открывается из раздела «Игры».'),
    jsonb_build_object('kind','new','scope','site','min_rank',4,'text','В «Экзамене-кластере» появилась вкладка «Из готовых билетов»: книжка НЦТ на русском и таджикском собирается из одного билета на предмет — из «Архива билетов» или из файлов Word, в том числе сборников не из системы; можно собрать книжку только по химии и биологии.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',4,'text','В «Качестве банка» пары, похожие на 90 % и меньше, больше не показываются: остаются только близкие дубли.'),
    jsonb_build_object('kind','new','scope','site','min_rank',2,'text','Раздел «Качество банка» открыт админам по предметам: они видят ошибки и похожие вопросы своих предметов и могут отмечать пары «Не дубль».')
  ),
  '2026-12-06 12:00:00+05');
